document.addEventListener("DOMContentLoaded",function(){var e=document.createElement("div");e.classList.add("tx-cursor-ring"),document.body.appendChild(e);var t=document.createElement("div");t.classList.add("tx-cursor-pointer"),document.body.appendChild(t),document.addEventListener("mousemove",function(n){e.style.transform=`translate3d(calc(${n.clientX}px - 50%), calc(${n.clientY}px - 50%), 0)`,t.style.left=n.clientX+"px",t.style.top=n.clientY+"px"}),document.addEventListener("mousedown",function(){e.classList.add("click"),t.classList.add("tx-cursor-inner")}),document.addEventListener("mouseup",function(){e.classList.remove("click"),t.classList.remove("tx-cursor-inner")})});